237	    StateFile good = read_state_file(path);
238	    CHECK(good.ok());
239	    CHECK(good.error.empty());
240	    CHECK(good.st.mcycle == 123456);
241	    CHECK(good.st.minstret == 7890);
242	    CHECK(good.st.flags == (HYBRID_FLAG_RV64 | HYBRID_FLAG_V));
243	    CHECK(good.st.vlenb == 64);
244	
245	    // a bad magic is rejected
246	    st.magic = 0xdeadbeefu;
247	    int fd2 = open(path, O_WRONLY | O_TRUNC);
248	    CHECK(fd2 >= 0);
249	    CHECK(write(fd2, &st, sizeof(st)) == static_cast<ssize_t>(sizeof(st)));
250	    close(fd2);
251	    CHECK(!read_state_file(path).ok());
252	
253	    // a truncated file (wrong size) is rejected
254	    st.magic = HYBRID_STATE_MAGIC;
255	    int fd3 = open(path, O_WRONLY | O_TRUNC);
256	    CHECK(fd3 >= 0);
257	    CHECK(write(fd3, &st, 16) == 16);
258	    close(fd3);
259	    CHECK(!read_state_file(path).ok());
260	
261	    unlink(path);
262	  }
263	
264	  // --- ABI v6: CSR write-mask (HYBRID_FLAG_WRITE_MASK + write_mask[2]) ---
265	  {
266	    // The wire format is at v6 now that the write-mask exists.
267	    CHECK(HYBRID_STATE_VERSION == 6u);
268	
269	    // The flag is a distinct bit after L2C.
270	    CHECK(HYBRID_FLAG_WRITE_MASK == (1u << 6));
271	    CHECK((HYBRID_FLAG_WRITE_MASK & HYBRID_FLAG_L2C) == 0u);
272	
273	    // Slot map: 13 Andes scalars + 2 pmacfg + 16 pmaaddr + 51 M-ext +
274	    // mcache_ctl + mmisc_ctl = 84 slots, fitting the 128-bit mask.
275	    CHECK(HYBRID_WM_ANDES_BASE == 0);
276	    CHECK(HYBRID_WM_PMACFG_BASE == 13);
277	    CHECK(HYBRID_WM_PMAADDR_BASE == 15);
278	    CHECK(HYBRID_WM_M_EXT_BASE == 31);
279	    CHECK(HYBRID_WM_MCACHE_CTL == 82);
280	    CHECK(HYBRID_WM_MMISC_CTL == 83);
281	    CHECK(HYBRID_WM_SLOT_COUNT == 84);
282	
283	    // set/test helpers round-trip, including a slot in the second word.
284	    hybrid_state_v1 st{};
285	    CHECK(hybrid_wm_test(st.write_mask, HYBRID_WM_MCACHE_CTL) == 0);
286	    hybrid_wm_set(st.write_mask, HYBRID_WM_MCACHE_CTL);   // slot 82: word 1
287	    hybrid_wm_set(st.write_mask, HYBRID_WM_ANDES_BASE);   // slot 0: word 0
288	    CHECK(hybrid_wm_test(st.write_mask, HYBRID_WM_MCACHE_CTL) == 1);
289	    CHECK(hybrid_wm_test(st.write_mask, HYBRID_WM_ANDES_BASE) == 1);
290	    CHECK(hybrid_wm_test(st.write_mask, HYBRID_WM_MMISC_CTL) == 0);
291	
292	    // The mask rides the state file: round-trip through read_state_file.
293	    st.magic = HYBRID_STATE_MAGIC;
294	    st.version = HYBRID_STATE_VERSION;
295	    st.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_WRITE_MASK;
296	    char path[] = "/tmp/andesim-state-wm.XXXXXX";
297	    int fd = mkstemp(path);
298	    CHECK(fd >= 0);
299	    CHECK(write(fd, &st, sizeof(st)) == static_cast<ssize_t>(sizeof(st)));
300	    close(fd);
301	    StateFile good = read_state_file(path);
302	    CHECK(good.ok());
303	    CHECK(hybrid_wm_test(good.st.write_mask, HYBRID_WM_MCACHE_CTL) == 1);
304	    CHECK(hybrid_wm_test(good.st.write_mask, HYBRID_WM_MMISC_CTL) == 0);
305	    unlink(path);
306	  }
307	
308	  // --- ABI v5: L2C MMIO register window (HYBRID_FLAG_L2C + hybrid_l2c.reg[]) ---
309	  {
310	
311	    // The L2C flag is a distinct bit, not colliding with the v4 blocks.
312	    CHECK(HYBRID_FLAG_L2C == (1u << 5));
313	    CHECK((HYBRID_FLAG_L2C & HYBRID_FLAG_M_EXT) == 0u);
314	    CHECK((HYBRID_FLAG_L2C & HYBRID_FLAG_ANDES) == 0u);
315	
316	    // The window is the full 0x0000..0x0527 register block (DS220 Table 112).
317	    CHECK(sizeof(hybrid_l2c) == 1320u);
318	    CHECK(HYBRID_L2C_OFF_CONTROL == 0x0008u);
319	    CHECK(HYBRID_L2C_OFF_WAYMASK0 == 0x0300u);
320	
321	    // A value at the Control Register offset round-trips through a state file.
322	    hybrid_state_v1 st{};
323	    st.magic = HYBRID_STATE_MAGIC;
324	    st.version = HYBRID_STATE_VERSION;
325	    st.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_L2C;
326	    st.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0x1;  // DS220 11.8.7: CEN=1
327	
328	    char path[] = "/tmp/andesim-state-l2c.XXXXXX";
329	    int fd = mkstemp(path);
330	    CHECK(fd >= 0);
331	    CHECK(write(fd, &st, sizeof(st)) == static_cast<ssize_t>(sizeof(st)));
332	    close(fd);
