// --- U10b: --mode fast --runtime linux has a --mem-size ceiling ---
// vlinux computes its arenas from ram_base == 0 today, so anything past the
// 2 GiB DRAM window puts the initial stack in the AE350 unmapped hole
// (measured 2026-07-29: a 3G fast run trap-storms instead of erroring).
{
  // within the window -> no error (2G exactly is the proven-good maximum:
  // the 8B fast run at 2G succeeds, stack top == 0x8000_0000 grows down)
  CHECK(fast_linux_mem_error("2G").empty());
  CHECK(fast_linux_mem_error("1G").empty());
  CHECK(fast_linux_mem_error("2097148K").empty());
  // empty spec: the 1G default is applied later, nothing to reject
  CHECK(fast_linux_mem_error("").empty());
  // past the window -> a message naming the flag, the cap and the runtime
  const std::string e = fast_linux_mem_error("3G");
  CHECK(!e.empty());
  CHECK(e.find("--mem-size") != std::string::npos);
  CHECK(e.find("2G") != std::string::npos);
  CHECK(e.find("linux") != std::string::npos);
  // malformed specs are qemu_m_args's business, not this check's
  CHECK(fast_linux_mem_error("8X").empty());
}

toolUseResult.oldString:
  err.clear();
  // malformed spec -> error
  CHECK(qemu_m_args("8X", err).empty() && !err.empty());
}

